`timescale 1ns/1ps
module tb;
  int i, j;
  logic [7:0] v;
  logic signed [7:0] s;
  initial begin
    i = 5;
    i++;
    $display("AO1 i++ -> %0d", i);
    i--;
    $display("AO2 i-- -> %0d", i);
    ++i;
    $display("AO3 ++i -> %0d", i);
    j = i++;
    $display("AO4 j=i++ j=%0d i=%0d", j, i);
    j = ++i;
    $display("AO5 j=++i j=%0d i=%0d", j, i);
    j = i--;
    $display("AO6 j=i-- j=%0d i=%0d", j, i);
    i += 10;
    $display("AO7 += %0d", i);
    i -= 3;
    $display("AO8 -= %0d", i);
    i *= 4;
    $display("AO9 *= %0d", i);
    i /= 3;
    $display("AO10 /= %0d", i);
    i %= 7;
    $display("AO11 %%= %0d", i);
    v = 8'b1010_0101;
    v &= 8'hF0;
    $display("AO12 &= %b", v);
    v |= 8'h0C;
    $display("AO13 |= %b", v);
    v ^= 8'hFF;
    $display("AO14 ^= %b", v);
    v <<= 2;
    $display("AO15 <<= %b", v);
    v >>= 3;
    $display("AO16 >>= %b", v);
    s = -8'sd64;
    s >>>= 2;
    $display("AO17 >>>= %0d %b", s, s);
    s <<<= 1;
    $display("AO18 <<<= %0d", s);
    v = 8'hFF;
    v++;
    $display("AO19 v++ wrap %0d", v);
    v = 8'h00;
    v--;
    $display("AO20 v-- wrap %0d", v);
    i = 3;
    i += i++;
    $display("AO21 i += i++ -> %0d", i);
    j = (i = 9) + 1;
    $display("AO22 assign in expr j=%0d i=%0d", j, i);
    $finish;
  end
endmodule
